function frame(now){const dt=clamp((now-lastTime)/1000,0,.033);lastTime=now;if(!document.hidden&&!panel.open){for(let i=0;i<currentColors.length;i++)currentColors[i]+=(targetColors[i]-currentColors[i])*(reduced?1:Math.min(1,dt*5));if(!paused)clock+=dt;nodes.forEach(n=>{const idle=!paused?Math.sin(clock*.5+n.phase)*7:0;const idleY=!paused?Math.cos(clock*.4+n.phase)*9:0;const tx=n.drag?n.px:n.homeX+idle,ty=n.drag?n.py:n.homeY+idleY;const stiffness=n.drag?125:21,damping=n.drag?23:8.7;if(reduced){n.x=tx;n.y=ty;n.vx=n.vy=0}else{n.vx+=((tx-n.x)*stiffness-n.vx*damping)*dt;n.vy+=((ty-n.y)*stiffness-n.vy*damping)*dt;n.x+=n.vx*dt;n.y+=n.vy*dt;}const target=n.hover&&!n.drag?1.035:1;n.scale+=(target-n.scale)*Math.min(1,dt*6);n.press+=((n.drag?1:0)-n.press)*Math.min(1,dt*9)});for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=b.x-a.x,dy=b.y-a.y,dist=Math.max(1,Math.hypot(dx,dy)),gap=(a.r+b.r)*.98;if(dist<gap){const force=(gap-dist)*12*dt,fx=dx/dist*force,fy=dy/dist*force;if(!a.drag){a.vx-=fx;a.vy-=fy}if(!b.drag){b.vx+=fx;b.vy+=fy}}}paintNodes();render()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
