function openPanel(view,origin){if(view==='home'){closePanel();return}if(closing)return;if(panel.open){setPage(view);content.querySelector('.panel-title')?.setAttribute('tabindex','-1');content.querySelector('.panel-title')?.focus({preventScroll:true});return}lastOrigin=origin||document.activeElement;setPage(view);panel.showModal();document.body.style.overflow='hidden';const rect=panel.getBoundingClientRect(),source=lastOrigin?.getBoundingClientRect();const dx=source?source.left+source.width/2-(rect.left+rect.width/2):0,dy=source?source.top+source.height/2-(rect.top+rect.height/2):30;panel._source={dx,dy};if(!reduced)panel.animate([{opacity:0,transform:`translate(${dx*.65}px,${dy*.65}px) scale(.38)`,borderRadius:'160px'},{opacity:1,transform:'translate(0,0) scale(1.006)',borderRadius:'52px',offset:.8},{opacity:1,transform:'translate(0,0) scale(1)',borderRadius:'52px'}],{duration:650,easing:'cubic-bezier(.16,1,.3,1)'});$('.panel-close').focus({preventScroll:true})}
