document.addEventListener('click',e=>{const target=e.target.closest('[data-open]');if(target){openPanel(target.dataset.open,target);if(target.dataset.open!=='home')chime(3)}const project=e.target.closest('[data-project]');if(project){openPanel(project.dataset.project,project);chime(7)}});$('.panel-close').addEventListener('click',closePanel);panel.addEventListener('cancel',e=>{e.preventDefault();closePanel()});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});
